<?php declare(strict_types=1);use App\Helpers\View;$e=static fn($x)=>htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');ob_start();?><div class="btp-shell btp-workspace"><nav class="btp-breadcrumb"><a href="<?= $e(View::url('btp/bons-commande')) ?>">Bons de commande</a><span>/</span><strong>Nouveau BC</strong></nav><header class="btp-banner"><small>COMMANDE CLIENT</small><h1><i class="fa-solid fa-file-circle-plus"></i> Nouveau bon de commande</h1><p>Choisir le projet, reprendre le devis et joindre le BC signé ou reçu.</p></header><?php if($errorBtp): ?><p class="btp-error" role="alert"><?= $e($errorBtp) ?></p><?php endif; ?><section class="btp-panel btp-section"><form method="get" action="<?= $e(View::url('btp/bons-commande/nouveau')) ?>"><label>Projet <select name="projet" data-select-search data-placeholder="Rechercher un projet par référence, intitulé ou client..." required><option value="">Sélectionner</option><?php foreach($projetsBtp as $p): ?><option value="<?= (int)$p['id'] ?>" <?= (int)$p['id']===$selectedProjectBtp?'selected':'' ?>><?= $e($p['reference'].' · '.$p['intitule'].' · '.$p['client_nom']) ?></option><?php endforeach; ?></select></label><button type="submit">Charger les devis du projet</button></form></section><?php if($selectedProjectBtp): ?><section class="btp-panel btp-section"><h2>Enregistrement du BC</h2><form method="post" enctype="multipart/form-data" action="<?= $e(View::url('btp/bons-commande')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrfBtp) ?>"><input type="hidden" name="project_id" value="<?= (int)$selectedProjectBtp ?>"><label>Référence du BC <input name="reference" maxlength="80" required></label><label>Date de réception <input type="date" name="received_at" required></label><label>Devis de référence <select name="offer_id" id="bc-offer" data-select-search data-placeholder="Rechercher un devis ou une révision..." required><option value="">Choisir le devis</option><?php foreach($offersBtp as $o): ?><option value="<?= (int)$o['id'] ?>">Révision <?= (int)$o['revision'] ?> · <?= $e($o['title']) ?> · <?= number_format((float)$o['total_ht'],2,',',' ') ?> FCFA HT</option><?php endforeach; ?></select></label><p class="btp-help">Toutes les lignes du devis sélectionné sont reprises automatiquement côté serveur, sans modification silencieuse. Le déboursé sera préparé à l'étape suivante.</p><div class="btp-bc-upload"><span class="btp-bc-field-title">Fichier justificatif du bon de commande</span><label class="btp-upload-zone btp-bc-dropzone" data-dropzone for="btp-bc-file"><i class="fa-solid fa-cloud-arrow-up" aria-hidden="true"></i><strong>Glissez votre document ici</strong><span>ou cliquez pour parcourir vos fichiers</span><small>Tous formats acceptés · 20 Mo maximum</small><input type="file" id="btp-bc-file" name="document" required><span class="btp-bc-file-preview" data-file-preview aria-live="polite"></span></label></div><button type="submit" <?= !$offersBtp?'disabled':'' ?>>Enregistrer le bon de commande</button></form><?php if(!$offersBtp): ?><p class="btp-error">Créez d'abord un devis pour ce projet.</p><?php endif; ?></section><?php endif; ?></div><?php $content=ob_get_clean();$additionalScripts=array_merge($additionalScripts??[],['js/components/form-components.js']);require BASE_PATH.'/views/layouts/module.php';